import type { TodoGateway } from './TodoGateway'
import type { TodoViewModel } from './TodoViewModel'

export class ListTodos {
  private readonly todos: TodoGateway

  constructor(todos: TodoGateway) {
    this.todos = todos
  }

  async execute(signal?: AbortSignal): Promise<TodoViewModel[]> {
    const records = await this.todos.list(signal)
    return records.map((record) => ({
      id: record.id,
      title: record.title,
      status: record.done ? 'done' : 'open',
    }))
  }
}
export type TodoRecord = {
  readonly id: string
  readonly title: string
  readonly done: boolean
}

/** The todos API owns the todos; this is how the application reaches it. */
export interface TodoGateway {
  list(signal?: AbortSignal): Promise<TodoRecord[]>
}
export type TodoViewModel = {
  readonly id: string
  readonly title: string
  readonly status: 'open' | 'done'
}
import type { TodoViewModel } from './TodoViewModel'

/** The line shown above the list: how far the user has got. */
export const progress = (todos: readonly TodoViewModel[]): string => {
  if (todos.length === 0) return 'Nothing to do'
  const done = todos.filter((todo) => todo.status === 'done').length
  if (done === todos.length) return 'All done'
  return `${done} of ${todos.length} done`
}
import { describe, expect, it } from 'vitest'

import { ListTodos } from '../../../../src/todos/application/ListTodos'
import { InMemoryTodoGateway } from '../InMemoryTodoGateway'

describe('ListTodos', () => {
  it('should describe each todo as open or done', async () => {
    const listTodos = new ListTodos(
      new InMemoryTodoGateway([
        { id: '1', title: 'Buy milk', done: false },
        { id: '2', title: 'Pay rent', done: true },
      ]),
    )

    expect(await listTodos.execute()).toEqual([
      { id: '1', title: 'Buy milk', status: 'open' },
      { id: '2', title: 'Pay rent', status: 'done' },
    ])
  })
})
import type { TodoGateway, TodoRecord } from '../../../src/todos/application/TodoGateway'

export class InMemoryTodoGateway implements TodoGateway {
  private readonly records: TodoRecord[]

  constructor(records: TodoRecord[] = []) {
    this.records = [...records]
  }

  list(): Promise<TodoRecord[]> {
    return Promise.resolve([...this.records])
  }
}
